/// The IQ types' codebooks: ggml-common.h's grids (llama.cpp, MIT) as llama.cpp's gguf-py packs them, hex bytes of
/// indices into a short list of values, lowest bits first (2-bit indices four to a byte, 3-bit ones one to a nibble).
/// Decoded once to one byte per value, entry-major; the Metal tables in `GGMLMatrixKernels` are built from these, so CPU
/// and GPU read the same codebook that `gguf_dequantize` checks against gguf-py.
extension GGUFQuant {
    static let iq2xxsGrid = grid(iq2xxsHex, bits: 2, values: [0x08, 0x19, 0x2b])
    static let iq2xsGrid = grid(iq2xsHex, bits: 2, values: [0x08, 0x19, 0x2b])
    static let iq2sGrid = grid(iq2sHex, bits: 2, values: [0x08, 0x19, 0x2b])
    static let iq3xxsGrid = grid(iq3xxsHex, bits: 3, values: [0x04, 0x0c, 0x14, 0x1c, 0x24, 0x2c, 0x34, 0x3e])
    static let iq3sGrid = grid(iq3sHex, bits: 3, values: [1, 3, 5, 7, 9, 11, 13, 15])
    /// IQ1_S and IQ1_M: value + 1 (the codebook holds -1, 0 and 1).
    static let iq1sGrid = grid(iq1sHex, bits: 2, values: [0, 1, 2])
    /// Eight sign bits from seven: the eighth makes the count of minus signs even.
    static let ksigns: [UInt8] = (0..<128).map { UInt8($0 | ($0.nonzeroBitCount & 1) << 7) }

    private static func grid(_ hex: String, bits: Int, values: [UInt8]) -> [UInt8] {
        let digits = Array(hex.utf8).filter { $0 > 32 }.map { $0 > 0x40 ? ($0 + 9) & 15 : $0 & 15 }
        let shift = bits == 2 ? 2 : 4
        return stride(from: 0, to: digits.count, by: 2).flatMap { i -> [UInt8] in
            let byte = digits[i] << 4 | digits[i + 1]
            return stride(from: 0, to: 8, by: shift).map { values[Int((byte >> UInt8($0)) & UInt8((1 << bits) - 1))] }
        }
    }

